"const fs = require('fs');
const path = require('path');

const projectDir = 'd:\\AI\\Antigravity';

// 1. Read index.html
const htmlContent = fs.readFileSync(path.join(projectDir, 'index.html'), 'utf8');

// Find all elements with ID starting with screen- or class with screen
console.log('--- SCREENS IN INDEX.HTML ---');
const screenRegex = /id=["'](screen-[a-zA-Z0-9_-]+)["']/g;
let match;
const screens = new Set();
while ((match = screenRegex.exec(htmlContent)) !== null) {
    screens.add(match[1]);
}
console.log(Array.from(screens));

// Find major section headings or navigation items
console.log('\n--- NAVIGATION ITEMS ---');
const navRegex = /data-target=["']([a-zA-Z0-9_-]+)["']/g;
const navItems = new Set();
while ((match = navRegex.exec(htmlContent)) !== null) {
    navItems.add(match[1]);
}
console.log(Array.from(navItems));

// Find inline script source or references
console.log('\n--- SCRIPTS ---');
const scriptRegex = /<script[^>]*src=["']([^"']+)["']/g;
const scripts = [];
while ((match = scriptRegex.exec(htmlContent)) !== null) {
    scripts.push(match[1]);
}
console.log(scripts);

// Find forms or action components
console.log('\n--- FORMS / INTERACTIVE MODULES ---');
const formRegex = /<form[^>]*id=["']([^"']+)["']/g;
const forms = [];
while ((match = formRegex.exec(htmlContent)) !== null) {
    forms.push(match[1]);
}
console.log(forms);

// 2. Read app.js to find routes or API endpoints called
console.log('\n--- API CALLS IN APP.JS ---');
const appContent = fs.readFileSync(path.join(projectDir, 'app.js'), 'utf8');
const fetchRegex = /fetch\s*\(\s*["'`](\/api\/[a-zA-Z0-9_-]+|https?:\/\/[^\s"'`]+)["'`]/g;
const apiCalls = new Set();
while ((match = fetchRegex.exec(appContent)) !== null) {
    apiCalls.add(match[1]);
}
console.log(Array.from(apiCalls));
